#!/usr/bin/env bash
jq -r 'select(.type=="assistant" and .message.usage) | .message.usage | (.input_tokens + (.cache_read_input_tokens//0) + (.cache_creation_input_tokens//0))' "$1" | awk 'NR==1{min=$1} {if($1>max)max=$1; last=$1; n++} END{printf "turns=%d ctx_first=%dk ctx_max=%dk ctx_last=%dk\n", n, min/1000, max/1000, last/1000}'
echo "compactions=$(grep -c '"isCompactSummary":true' "$1")  models=$(jq -r 'select(.type=="assistant")|.message.model' "$1" | sort | uniq -c | awk '{printf "%s:%s ",$2,$1}')"
sub="${1%.jsonl}/subagents"; [ -d "$sub" ] && cat "$sub"/*.jsonl | jq -r 'select(.type=="assistant" and .message.usage) | .message.usage as $u | [($u.cache_read_input_tokens//0), ($u.cache_creation_input_tokens//0), ([.message.content[]? | select(.type=="tool_use")] | length)] | @tsv' | awk -v n="$(ls "$sub"/*.jsonl | wc -l | tr -d ' ')" '{r+=$1; w+=$2; t+=$3} END {printf "sub_agents=%d sub_tools=%d sub_cache_read=%.1fM sub_cache_write=%.2fM\n", n, t, r/1e6, w/1e6}'
